// SDS Traduction — tout-en-un (Cloudflare Worker + Durable Objects + Workers AI)
// Ce fichier contient le serveur ET l'application. Aucune base de données à créer.
// Secret à créer dans Cloudflare après la mise en ligne : ADMIN_KEY (clé administrateur, 32 caractères ou plus)

import { DurableObject } from 'cloudflare:workers';

// ---------- Réglages ----------
const ADMIN_TOKEN_DAYS = 7;          // durée de la session administrateur
const TICKET_SECONDS = 60;           // durée d'un ticket d'entrée dans un salon
const ROOM_HOURS = 12;               // durée de vie d'un salon
const CONV_MAX = 3;                  // nombre max d'interlocuteurs en conversation
const CONSOLE_MAX = 1000;            // nombre max d'auditeurs en mode console
const MAX_TEXT = 500;                // longueur max d'une phrase
const TRANSLATE_MODEL = '@cf/meta/m2m100-1.2b';

// ---------- Outils ----------
const ALPHA = 'abcdefghjkmnpqrstuvwxyz23456789';
const ROOM_ALPHA = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
function randStr(n, alpha) {
  const lim = 256 - (256 % alpha.length); // rejet pour éviter le biais du modulo
  const out = [];
  while (out.length < n) {
    for (const v of crypto.getRandomValues(new Uint8Array(n * 2))) {
      if (v < lim) out.push(alpha[v % alpha.length]);
      if (out.length === n) break;
    }
  }
  return out.join('');
}
const hex = b => [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join('');
const sha = async s => hex(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(String(s))));
const rnd = n => hex(crypto.getRandomValues(new Uint8Array(n)));
async function hmac(key, msg) {
  const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return hex(await crypto.subtle.sign('HMAC', k, new TextEncoder().encode(msg)));
}
function eq(a, b) {
  a = String(a); b = String(b);
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
const lang = v => (v === 'en' ? 'en' : 'fr');
const clean = (v, n) => String(v || '').replace(/[\u0000-\u001f<>]/g, '').trim().slice(0, n);
const b64 = s => btoa(unescape(encodeURIComponent(s))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb64 = s => decodeURIComponent(escape(atob(s.replace(/-/g, '+').replace(/_/g, '/'))));

function corsHeaders(env, req) {
  const origin = req.headers.get('Origin');
  const allowed = String(env.ALLOWED_ORIGINS || '').split(',').map(s => s.trim()).filter(Boolean);
  if (!origin || !allowed.includes(origin)) return { Vary: 'Origin' };
  return {
    Vary: 'Origin',
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, x-adm',
    'Access-Control-Max-Age': '86400'
  };
}

// ---------- Jetons ----------
async function admOk(env, tok) {
  if (!tok || !env.ADMIN_KEY) return false;
  const [e, m] = String(tok).split('.');
  if (!e || !m || !(+e > Date.now())) return false;
  return eq(m, await hmac(env.ADMIN_KEY, 'adm.' + e));
}
async function makeTicket(env, data) {
  const p = b64(JSON.stringify({ ...data, exp: Date.now() + TICKET_SECONDS * 1000 }));
  return p + '.' + await hmac(env.ADMIN_KEY, 'tkt.' + p);
}
async function readTicket(env, t) {
  const [p, m] = String(t || '').split('.');
  if (!p || !m || !eq(m, await hmac(env.ADMIN_KEY, 'tkt.' + p))) return null;
  try {
    const d = JSON.parse(unb64(p));
    return d.exp > Date.now() ? d : null;
  } catch (e) { return null; }
}

const registry = env => env.REG.get(env.REG.idFromName('principal'));
const roomStub = (env, code) => env.ROOM.get(env.ROOM.idFromName(code));
const lobby = env => env.LOBBY.get(env.LOBBY.idFromName('principal'));
const pidOf = me => (me.role === 'admin' ? 'admin' : me.h.slice(0, 16));

// Qui fait la requête ? Administrateur (en-tête x-adm) ou appareil activé (champ dev)
async function whoAmI(env, req, b) {
  if (await admOk(env, req.headers.get('x-adm'))) return { h: 'ADMIN', role: 'admin', name: clean(b.name, 40) || 'Émetteur', lang: lang(b.lang) };
  if (!b.dev) return null;
  const h = await sha(b.dev);
  const d = await registry(env).who(h);
  if (!d) return null;
  return { h, role: 'user', name: clean(b.name, 40) || d.note || 'Invité', lang: lang(b.lang || d.lu) };
}

